 "content": "from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # A repeated row provides a reference; mark a differing right-hand tail
    # when the target tail is background and the reference carries a pattern.
    for i in range(h):
        for j in range(h):
            if i == j:
                continue
            a, b = grid[i], grid[j]  # a target, b reference
            k = w - 1
            while k >= 0 and a[k] != b[k]:
                k -= 1
            start = k + 1
            if start == w:
                continue
            if not all(v == bg for v in a[start:]):
                continue
            if not all(v != bg for v in b[start:]):
                continue
            # The preceding portions must describe substantially the same row.
            if k < 0:
                continue
            similarity = sum(a[x] == b[x] for x in range(k + 1)) / (k + 1)
            if similarity < 0.65:
                continue
            if not any(v != bg for v in a[:start]):
                continue
            for x in range(start, w):
                out[i][x] = 1
    return out
